PARSE-001.bad_pattern:
func my_fn() -> trit {  // 'func' is not a keyword in .tern
    return truth();
}

PARSE-004.bad_pattern:
match signal {
    -1 => { return conflict(); }
     1 => { return truth();   }
    // missing 0 arm — compiler rejects this
}

PARSE-004.good_pattern:
match signal {
    -1 => { return conflict(); }
     0 => { return hold();    }
     1 => { return truth();   }
}

STRUCT-002.bad_pattern:
struct Gate { state: trit }
let g: Gate = Gate { state: 1 };
let v: trit = g.value;  // 'value' doesn't exist, field is 'state'

STRUCT-002.good_pattern:
struct Gate { state: trit }
let g: Gate = Gate { state: 1 };
let v: trit = g.state;  // correct field name

FN-001.good_pattern:
fn evaluate(v: trit) -> trit {
    return v;
}
let x: trit = evaluate(1);

FN-002.bad_pattern:
fn gate(v: trit) -> trit {
    return 42;  // 42 is int, not trit
}

FN-002.good_pattern:
fn gate(v: trit) -> trit {
    return v;   // trit in, trit out
}

FN-003.bad_pattern:
fn combine(a: trit, b: trit) -> trit {
    return consensus(a, b);
}
let r: trit = combine(1);  // missing second argument

FN-003.good_pattern:
fn combine(a: trit, b: trit) -> trit {
    return consensus(a, b);
}
let r: trit = combine(1, 0);  // both arguments provided

BET-001.bad_pattern:
fn gate(v: trit) -> trit {
    match v {
        -1 => { return conflict(); }
         1 => { return truth();   }
        // 0 arm missing — if v==0, function returns nothing → stack underflow
    }
}

BET-001.good_pattern:
fn gate(v: trit) -> trit {
    match v {
        -1 => { return conflict(); }
         0 => { return hold();    }
         1 => { return truth();   }
    }
}

BET-007.bad_pattern:
fn mixed(v: trit) -> trit {
    match v {
        -1 => { return conflict(); }  // trit ✓
         0 => { return hold();    }  // trit ✓
         1 => { return 42;        }  // int! BET-007 at runtime
    }
}

BET-007.good_pattern:
fn pure(v: trit) -> trit {
    match v {
        -1 => { return conflict(); }
         0 => { return hold();    }
         1 => { return truth();   }  // trit ✓ — consistent
    }
}
